.MplusDiagnosticsHeatmapScale <- function(metric_name,
                                          comparison,
                                          threshold) {
  if (comparison == "difference") {
    if (metric_name == "ess") {
      low_colour <- "#B2182B"
      high_colour <- "#2166AC"
    } else {
      low_colour <- "#2166AC"
      high_colour <- "#B2182B"
    }
    return(
      list(
        scale_type = "diverging",
        threshold = 0,
        legend_title = "User - default",
        low_colour = low_colour,
        high_colour = high_colour
      )
    )
  }
  if (metric_name == "failure_rate") {
    return(
      list(
        scale_type = "sequential",
        threshold = 0,
        legend_title = "Failure rate",
        low_colour = "white",
        high_colour = "#B2182B"
      )
    )
  }
  if (metric_name == "ess") {
    low_colour <- "#B2182B"
    high_colour <- "#2166AC"
  } else {
    low_colour <- "#2166AC"
    high_colour <- "#B2182B"
  }
  list(
    scale_type = "diverging",
    threshold = threshold,
    legend_title = paste0(
      switch(metric_name,
        rhat = "R-hat",
        ess = "ESS",
        mcse = "MCSE"
      ),
      " - ",
      format(threshold, trim = TRUE)
    ),
    low_colour = low_colour,
    high_colour = high_colour
  )
}

.FormatMplusDiagHeatmapValue <- function(value,
                                         metric_name,
                                         comparison) {
  if (metric_name == "failure_rate") {
    if (comparison == "difference") {
      return(
        ifelse(
          is.finite(value),
          sprintf("%+.0f pp", 100 * value),
          NA_character_
        )
      )
    }
    return(
      ifelse(
        is.finite(value),
        sprintf("%.0f%%", 100 * value),
        NA_character_
      )
    )
  }
  if (metric_name == "ess") {
    return(
      ifelse(
        is.finite(value),
        if (comparison == "difference") {
          sprintf("%+.0f", value)
        } else {
          sprintf("%.0f", value)
        },
        NA_character_
      )
    )
  }
  ifelse(
    is.finite(value),
    if (comparison == "difference") {
      sprintf("%+.3f", value)
    } else {
      sprintf("%.3f", value)
    },
    NA_character_
  )
}

.MplusDiagHeatmapTextColour <- function(x,
                                        diverging) {
  finite <- x[is.finite(x)]
  if (length(finite) == 0L) {
    return(rep("black", length(x)))
  }
  if (diverging) {
    boundary <- 0.65 * max(abs(finite))
    if (!is.finite(boundary) || boundary == 0) {
      return(rep("black", length(x)))
    }
    ifelse(
      is.finite(x) & abs(x) >= boundary,
      "white",
      "black"
    )
  } else {
    boundary <- unname(
      stats::quantile(
        finite,
        probs = 0.75,
        names = FALSE,
        type = 8
      )
    )
    ifelse(
      is.finite(x) & x >= boundary,
      "white",
      "black"
    )
  }
}

.ValidateMplusDiagThreshold <- function(x,
                                        name,
                                        lower) {
  if (
    length(x) != 1L ||
      !is.numeric(x) ||
      !is.finite(x) ||
      x <= lower
  ) {
    stop(
      paste0(
        "`",
        name,
        "` should be a finite numeric value greater than ",
        lower,
        "."
      ),
      call. = FALSE
    )
  }
  invisible(x)
}

.FilterMplusDiagHeatmapTask <- function(x,
                                        taskid = NULL) {
  if (is.null(taskid)) {
    return(x)
  }
  if (
    !is.numeric(taskid) ||
      length(taskid) == 0L ||
      any(!is.finite(taskid)) ||
      any(taskid != floor(taskid)) ||
      any(taskid < 1L)
  ) {
    stop(
      "`taskid` should contain positive integers.",
      call. = FALSE
    )
  }
  out <- x[x$taskid %in% as.integer(taskid), , drop = FALSE]
  if (nrow(out) == 0L) {
    stop(
      "No parameter diagnostics matched the requested `taskid` values.",
      call. = FALSE
    )
  }
  out
}

.SelectMplusDiagHeatmapParms <- function(parameters,
                                         parm = NULL) {
  if (!is.data.frame(parameters) || !"parameter" %in% names(parameters)) {
    stop(
      "`parameters` should be a data frame containing `parameter`.",
      call. = FALSE
    )
  }
  if (anyDuplicated(parameters$parameter)) {
    stop(
      "Parameter names in `parameters` should be unique.",
      call. = FALSE
    )
  }
  if (is.null(parm)) {
    return(parameters)
  }
  if (length(parm) == 0L) {
    stop(
      "`parm` should select at least one parameter.",
      call. = FALSE
    )
  }
  if (is.numeric(parm)) {
    if (
      any(!is.finite(parm)) ||
        any(parm != floor(parm)) ||
        any(parm < 1L) ||
        any(parm > nrow(parameters))
    ) {
      stop(
        "Numeric `parm` values should be valid positive integer positions.",
        call. = FALSE
      )
    }
    location <- as.integer(parm)
  } else if (is.character(parm)) {
    location <- match(parm, parameters$parameter)
    if (anyNA(location)) {
      stop(
        paste0(
          "Unknown parameters were requested: ",
          paste(unique(parm[is.na(location)]), collapse = ", "),
          "."
        ),
        call. = FALSE
      )
    }
  } else {
    stop(
      "`parm` should be `NULL`, numeric positions, or parameter names.",
      call. = FALSE
    )
  }
  parameters[unique(location), , drop = FALSE]
}
